def unique_digits(x):
    """Given a list of positive integers x. return a sorted list of all 
    elements that hasn't any even digit.

    Note: Returned list should be sorted in increasing order."""

    def has_no_even_digit(n):
        """Helper function to check if a number contains no even digits."""
        while n > 0:
            digit = n % 10
            if digit % 2 == 0:
                return False
            n //= 10
        return True

    result = []
    for num in x:
        if has_no_even_digit(num):
            result.append(num)

    return sorted(result)

# Example usage:
print(unique_digits([1, 33, 1422, 1]))  # Output: [1, 15, 33]
print(unique_digits([1552, 323, 1422, 10]))  # Output: []
```

