    """Check if a number is prime."""
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.

    """
    fib1, fib2 = 0, 1
    for _ in range(3, n):
        fib1, fib2 = fib2, fib1 + fib2
    if is_prime(fib2):
        return fib2
    return None

